  const titles = Object.fromEntries([...navItems, ['profile','user','Meu perfil'], ['session','play','Treino em andamento']].map(([id,,title]) => [id,title]));
  function render() {
    if (!authReady || !accountId) { renderAuth(); return; }
    if (!state) { state = R.seed(new Date(), accountId === 'demo'); save(); }
    page = location.hash.slice(1) || 'home'; if (!titles[page]) page = 'home';
    document.documentElement.dataset.screen = page;
    const views = { home: homeView, workouts: workoutsView, catalog: catalogView, history: historyView, progress: progressView, coach: coachView, profile: profileView, session: sessionView };
    $('#app').innerHTML = `<div class="shell"><aside class="sidebar">${brand()}<div class="nav-caption">SEU ESPAÇO DE TREINO</div><nav class="nav" aria-label="Navegação principal">${navItems.map(([id,i,t]) => `<a href="#${id}" class="nav-link ${page===id?'active':''}" ${page===id?'aria-current="page"':''}>${icon(i)}${t}${id==='coach'?'<span class="nav-pill">BETA</span>':''}</a>`).join('')}</nav><div class="side-bottom"><div class="demo-card"><b><span class="dot"></span>${accountId==='cloud'?'Sua conta RepWise':'Modo demonstração'}</b><p>${accountId==='cloud'?'Seu progresso acompanha você em qualquer aparelho.':'Explore o aplicativo com dados simulados.'}</p></div><button class="user-link" data-action="profile"><span class="avatar">${esc(initials(state.profile.name))}</span><span class="user-copy"><b>${esc(state.profile.name)}</b><small>Meu perfil e preferências</small></span>${icon('chevron')}</button></div></aside><main class="main"><header class="topbar">${brand('mobile-brand')}<div class="breadcrumb">Meu espaço<span>/</span><b>${titles[page]}</b></div><div class="top-actions">${window.RepWiseAppearance.button()}<span class="tag"><span class="dot"></span>${accountId==='cloud'?'MINHA CONTA':'DEMONSTRAÇÃO · MOCK'}</span><button class="icon-btn" data-action="about" aria-label="Sobre esta versão">${icon('info')}</button><button class="avatar" style="border:0;cursor:pointer" data-action="profile" aria-label="Abrir meu perfil">${esc(initials(state.profile.name))}</button></div></header>${!storage.available?'<div class="storage-alert" role="alert">Armazenamento indisponível. As alterações desta sessão podem não ser preservadas.</div>':''}<div id="sync-warning" class="storage-alert sync-warning" role="alert" ${syncError?'':'hidden'}><span data-sync-error>${esc(syncError)}</span><div><button class="btn small outline" data-action="sync-retry">Tentar novamente</button><button class="btn small outline" data-action="export-json">Exportar backup</button><button class="btn small outline" data-action="cloud-reload">Carregar versão da conta</button></div></div><div class="content view">${state.active && page!=='session'?`<div class="active-callout"><div><b>Seu treino está em andamento</b><p>${esc(state.active.name)} · ${accountId==='cloud'?'registros vinculados à sua conta':'registros salvos neste navegador'}</p></div><button class="btn small dark" data-action="resume">Continuar ${icon('arrow')}</button></div>`:''}${views[page]()}<footer class="footer"><span>RepWise AI © 2026 · Cada repetição conta.</span><span><span class="dot"></span><span data-sync-label>${accountId==='cloud'?esc(syncStatus):'Dados salvos neste navegador'}</span></span></footer></div></main><nav class="mobile-nav" aria-label="Navegação móvel">${[['home','grid','Início'],['workouts','dumbbell','Treinos'],['history','clock','Histórico'],['progress','chart','Evolução'],['coach','spark','Assistente']].map(([id,i,t]) => `<a href="#${id}" class="${page===id?'active':''}" ${page===id?'aria-current="page"':''}>${icon(i)}${t}</a>`).join('')}</nav></div>`;
    if (page === 'coach') scrollChat();
  }
  function intro(eyebrow, title, desc, action = '') { return `<div class="page-intro"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${desc}</p></div>${action}</div>`; }
  function stat(label, value, sub, i) { return `<div class="stat"><div class="stat-top">${label}${icon(i)}</div><strong>${value}</strong><div class="foot">${sub}</div></div>`; }
  function empty(title, desc, action='') { return `<div class="empty">${icon('dumbbell')}<h3>${title}</h3><p>${desc}</p>${action}</div>`; }
